#include "doitgen.h"

void kernel_doitgen(double A[10][8][12], double C4[12][12], double sum[12]) {
    int r, q, p, s;
    const int R = 10;
    const int Q = 8;
    const int S = 12;
    const int P = 12;

    for (r = 0; r < R; r++) {
        for (q = 0; q < Q; q++) {
            // Initialize sum array to 0 for this r,q combination
            for (p = 0; p < P; p++) {
                sum[p] = 0.0;
            }

            // Compute the sum for each p
            for (p = 0; p < P; p++) {
                for (s = 0; s < S; s++) {
                    sum[p] += A[r][q][s] * C4[p][s];
                }
            }

            // Store the results back in A (in-place)
            for (p = 0; p < P; p++) {
                A[r][q][p] = sum[p];
            }
        }
    }
}
```

